files.geo.meaning.yaml:
format: meaning/draft-1
id: geo
name: Geography
description: >-
  Places with a meaning shared across datasets: countries, cities, and the
  people who live in them. Starter subset: the country list holds a starter
  set of countries; the full ISO 3166-1 list comes later.
license: CC0-1.0
concepts:
  - id: country
    kind: entity
    labels:
      en: Country
      ru: Страна
    synonyms:
      en: [nation, countries]
      ru: [государство, страны]
    description: >-
      A country or territory with an ISO 3166-1 code, identified independently
      of any data source. Values are keyed by the lowercase ISO 3166-1 alpha-2
      code. A dataset that stores a country by name matches it against a
      value's labels and aliases; one that stores a code matches it against
      the value's codes.
    values:
      - id: ar
        labels: {en: Argentina, ru: Аргентина}
        codes: {alpha2: AR, alpha3: ARG, numeric: "032"}
      - id: au
        labels: {en: Australia, ru: Австралия}
        codes: {alpha2: AU, alpha3: AUS, numeric: "036"}
      - id: at
        labels: {en: Austria, ru: Австрия}
        codes: {alpha2: AT, alpha3: AUT, numeric: "040"}
      - id: be
        labels: {en: Belgium, ru: Бельгия}
        codes: {alpha2: BE, alpha3: BEL, numeric: "056"}
      - id: br
        labels: {en: Brazil, ru: Бразилия}
        codes: {alpha2: BR, alpha3: BRA, numeric: "076"}
      - id: ca
        labels: {en: Canada, ru: Канада}
        codes: {alpha2: CA, alpha3: CAN, numeric: "124"}
      - id: cl
        labels: {en: Chile, ru: Чили}
        codes: {alpha2: CL, alpha3: CHL, numeric: "152"}
      - id: cz
        labels: {en: Czechia, ru: Чехия}
        aliases:
          en: [Czech Republic]
          ru: [Чешская Республика]
        codes: {alpha2: CZ, alpha3: CZE, numeric: "203"}
      - id: dk
        labels: {en: Denmark, ru: Дания}
        codes: {alpha2: DK, alpha3: DNK, numeric: "208"}
      - id: fi
        labels: {en: Finland, ru: Финляндия}
        codes: {alpha2: FI, alpha3: FIN, numeric: "246"}
      - id: fr
        labels: {en: France, ru: Франция}
        codes: {alpha2: FR, alpha3: FRA, numeric: "250"}
      - id: de
        labels: {en: Germany, ru: Германия}
        codes: {alpha2: DE, alpha3: DEU, numeric: "276"}
      - id: hu
        labels: {en: Hungary, ru: Венгрия}
        codes: {alpha2: HU, alpha3: HUN, numeric: "348"}
      - id: in
        labels: {en: India, ru: Индия}
        codes: {alpha2: IN, alpha3: IND, numeric: "356"}
      - id: ie
        labels: {en: Ireland, ru: Ирландия}
        codes: {alpha2: IE, alpha3: IRL, numeric: "372"}
      - id: it
        labels: {en: Italy, ru: Италия}
        codes: {alpha2: IT, alpha3: ITA, numeric: "380"}
      - id: nl
        labels: {en: Netherlands, ru: Нидерланды}
        aliases:
          en: [The Netherlands, Holland]
          ru: [Голландия]
        codes: {alpha2: NL, alpha3: NLD, numeric: "528"}
      - id: "no"
        labels: {en: Norway, ru: Норвегия}
        codes: {alpha2: "NO", alpha3: NOR, numeric: "578"}
      - id: pl
        labels: {en: Poland, ru: Польша}
        codes: {alpha2: PL, alpha3: POL, numeric: "616"}
      - id: pt
        labels: {en: Portugal, ru: Португалия}
        codes: {alpha2: PT, alpha3: PRT, numeric: "620"}
      - id: es
        labels: {en: Spain, ru: Испания}
        codes: {alpha2: ES, alpha3: ESP, numeric: "724"}
      - id: se
        labels: {en: Sweden, ru: Швеция}
        codes: {alpha2: SE, alpha3: SWE, numeric: "752"}
      - id: gb
        labels: {en: United Kingdom, ru: Великобритания}
        aliases:
          en: [UK, Great Britain, Britain, United Kingdom of Great Britain and Northern Ireland]
          ru: [Соединённое Королевство, Британия]
        codes: {alpha2: GB, alpha3: GBR, numeric: "826"}
      - id: us
        labels: {en: United States, ru: США}
        aliases:
          en: [USA, US, United States of America, America]
          ru: [Соединённые Штаты, Соединённые Штаты Америки, Америка]
        codes: {alpha2: US, alpha3: USA, numeric: "840"}

  - id: country-code
    kind: attribute
    of: country
    labels:
      en: Country code
      ru: Код страны
    synonyms:
      en: [ISO country code, ISO 3166 code, alpha-2 code, alpha-3 code]
    description: >-
      An ISO 3166-1 code that identifies a country: alpha-2 ("IE"), alpha-3
      ("IRL") or numeric ("372"). Each country value lists all three.

  - id: city
    kind: entity
    labels:
      en: City
      ru: Город
    synonyms:
      en: [town, cities]
      ru: [населённый пункт, города]
    description: >-
      A named settlement located within a country. No known values yet: city
      names repeat across countries, so a dataset matches a city together
      with its country.

  - id: population
    kind: measure
    of: country
    labels:
      en: Population
      ru: Население
    synonyms:
      en: [number of people, inhabitants, residents]
      ru: [численность населения, жители, количество людей]
    description: >-
      The number of people living in a country at a point in time. Always
      state the year: populations change every year and sources differ.
    unit: people
    measure:
      formula: The count of residents of the country in the stated year.
      aggregation: none
